from typing import List

def articulationPoints(V: int, adj: List[List[int]]) -> List[int]:
    if V == 1:
        return [-1]

    time = 0
    discovery = [-1] * V
    low = [-1] * V
    visited = [False] * V
    is_articulation = [False] * V
    parent = [-1] * V

    def dfs(u):
        nonlocal time
        children = 0
        visited[u] = True
        discovery[u] = low[u] = time
        time += 1

        for v in adj[u]:
            if not visited[v]:
                children += 1
                parent[v] = u
                dfs(v)
                low[u] = min(low[u], low[v])

                if parent[u] == -1 and children > 1:
                    is_articulation[u] = True
                if parent[u] != -1 and low[v] >= discovery[u]:
                    is_articulation[u] = True
            elif v != parent[u]:
                low[u] = min(low[u], discovery[v])

    for u in range(V):
        if not visited[u]:
            dfs(u)

    result = [u for u in range(V) if is_articulation[u]]
    if not result:
        return [-1]
    return sorted(result)
